mapper.update:
UPDATE workspace_task
SET assignee_staff_id = #{assigneeStaffId},
    gmt_modified = #{gmtModified}
WHERE id = #{id}
  AND status = 'OPEN'
  AND is_deleted = 0

UPDATE workspace_task
SET assignee_staff_id = #{staffId},
    gmt_modified = #{gmtModified}
WHERE org_id = #{orgId}
  AND people_id = #{peopleId}
  AND status = 'OPEN'
  AND assignee_staff_id IS NULL
  AND is_deleted = 0

UPDATE workspace_task
SET assignee_staff_id = #{toStaffId},
    gmt_modified = #{gmtModified}
WHERE org_id = #{orgId}
  AND people_id = #{peopleId}
  AND status = 'OPEN'
  AND assignee_staff_id = #{fromStaffId}
  AND is_deleted = 0

