  AND opened_at >= #{from}
  AND opened_at < #{to}
  AND is_deleted = 0
ORDER BY opened_at DESC, id DESC

mapper.sql:
FROM workspace_task t
WHERE t.org_id = #{orgId}
  AND t.is_deleted = 0

  AND t.tenant_id = #{tenantId}



        AND t.status = 'OPEN'
        AND t.assignee_staff_id IS NULL


        AND t.status = 'OPEN'
        AND t.assignee_staff_id = #{assigneeStaffId}


        AND t.status = 'DONE'
        AND (t.done_by_staff_id = #{assigneeStaffId} OR t.assignee_staff_id = #{assigneeStaffId})

            AND t.done_at >= #{doneFrom}


            AND t.done_at < #{doneTo}




            AND t.status = #{status}




    AND t.task_type = #{taskType}


    AND t.task_type NOT IN

        #{tp}



    AND EXISTS (
        SELECT 1 FROM care_team_member ctm
        WHERE ctm.org_id = t.org_id
          AND ctm.people_id = t.people_id
          AND ctm.member_type = 'PATIENT'
          AND ctm.team_id = #{careTeamId}
          AND ctm.is_deleted = 0
    )


    AND EXISTS (
        SELECT 1 FROM people_profile p
        WHERE p.id = t.people_id
          AND p.is_deleted = 0
          AND p.display_name LIKE CONCAT('%', #{keyword}, '%')
    )

